import{H as e,V as t,et as n,j as r}from"./chunks/framework.C_EfTa_6.js";var i=JSON.parse(`{"title":"QEMU 内核调试","description":"","frontmatter":{"title":"QEMU 内核调试","order":10},"headers":[],"relativePath":"kernel/vm/qemu.md","filePath":"kernel/vm/qemu.md"}`),a={name:`kernel/vm/qemu.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="qemu-内核调试" tabindex="-1">QEMU 内核调试 <a class="header-anchor" href="#qemu-内核调试" aria-label="Permalink to “QEMU 内核调试”">​</a></h1><p>QEMU 对内核开发者的价值远超&quot;跑一个虚拟机&quot;——它是内核调试最顺手的工具。真实的硬件调试需要 JTAG 探针、串口线缆和一块可能被调试错误烧毁的开发板，而 QEMU 把这一切虚拟化：GDB 可以附加到虚拟机内的任意状态、串口输出直接重定向到终端、物理内存和寄存器随时可以检查。内核开发中最有价值的反馈回路——&quot;修改 → 编译 → 启动 → 观察&quot;——在 QEMU 中可以被压缩到几十秒。</p><h2 id="gdb-调试内核" tabindex="-1">GDB 调试内核 <a class="header-anchor" href="#gdb-调试内核" aria-label="Permalink to “GDB 调试内核”">​</a></h2><p>QEMU 内置 GDB stub——在用户态模拟虚拟机的 CPU 状态，等待 GDB 连接。启动参数 <code>-s -S</code> 的含义：<code>-s</code> 在 TCP 1234 端口开放 GDB 服务，<code>-S</code> 让虚拟机在第一条指令处暂停等待调试器。</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 启动内核调试会话</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">qemu-system-x86_64</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -kernel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bzImage</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -initrd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> initramfs.cpio.gz</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -append</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;console=ttyS0 nokaslr&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -nographic</span></span></code></pre></div><p><code>nokaslr</code> 是内核调试的标配——KASLR 让内核地址每次启动随机化，调试符号和断点会全部失效。在另一个终端连接 GDB：</p><div class="language-gdb"><button title="Copy Code" class="copy"></button><span class="lang">gdb</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># gdb vmlinux</span></span>
<span class="line"><span>(gdb) target remote :1234</span></span>
<span class="line"><span>(gdb) b start_kernel</span></span>
<span class="line"><span>(gdb) c</span></span></code></pre></div><p>断点命中后，<code>bt</code> 查看调用栈、<code>info registers</code> 查看寄存器、<code>x/20x $rsp</code> 查看栈内容——与调试普通用户态程序完全相同的体验，但被调试对象是内核启动早期的代码。</p><p>调试内核模块的常用技巧：模块在加载时地址动态分配，断点需要延迟设置。先在 <code>module_init</code> 函数入口打断点确认模块代码段基址，再根据符号偏移计算内部函数的实际地址：</p><div class="language-gdb"><button title="Copy Code" class="copy"></button><span class="lang">gdb</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 模块加载后</span></span>
<span class="line"><span>(gdb) p &amp;my_module_init      # 得到模块加载基址</span></span>
<span class="line"><span>(gdb) b *($lx_symbol(&quot;my_driver_ioctl&quot;) )   # 计算偏移后的实际地址</span></span></code></pre></div><h2 id="串口控制台-内核的眼睛" tabindex="-1">串口控制台：内核的眼睛 <a class="header-anchor" href="#串口控制台-内核的眼睛" aria-label="Permalink to “串口控制台：内核的眼睛”">​</a></h2><p><code>-nographic</code> 把虚拟串口重定向到当前终端，内核启动参数 <code>console=ttyS0</code> 让内核的 printk 输出走串口。这解决了内核调试最基础的痛点——内核启动早期的日志在图形控制台上稍纵即逝，串口输出则可以完整捕获、搜索、保存。</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 将串口输出同时保存到文件</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">qemu-system-x86_64</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -kernel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bzImage</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -initrd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> initramfs.cpio.gz</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -append</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;console=ttyS0 nokaslr&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -nographic</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> tee</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boot.log</span></span></code></pre></div><p>对于调试 panic 场景，串口是唯一可靠的输出通道——panic 时图形栈和网络栈都可能已经损坏，但串口驱动是内核中最早初始化、最晚失效的组件。<code>panic=-1</code> 参数让内核 panic 后立即重启，配合串口日志可以自动化&quot;反复崩溃采集&quot;的循环。</p><h2 id="内核错误捕获机制" tabindex="-1">内核错误捕获机制 <a class="header-anchor" href="#内核错误捕获机制" aria-label="Permalink to “内核错误捕获机制”">​</a></h2><p>QEMU 环境适合练习内核的各种错误捕获手段，因为可以安全地制造崩溃。</p><p><strong>oops 消息</strong>：内核在非致命错误（空指针解引用、栈溢出）时打印的调用栈回溯。<code>oops=panic</code> 让 oops 升级为 panic，避免状态继续恶化。oops 输出的函数地址可以用 <code>scripts/faddr2line</code> 工具解析为源码位置。</p><p><strong>panic 与 kdump</strong>：panic 是内核检测到不可恢复错误后的停机。kdump 机制在 panic 时用 kexec 启动一个专门的内核（dump 内核）来保存崩溃现场的内存镜像（vmcore），供事后用 crash 工具分析。QEMU 中练习 kdump 需要额外传递 crashkernel 参数：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">-append</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;console=ttyS0 nokaslr crashkernel=128M&quot;</span></span></code></pre></div><p><strong>动态探针</strong>：ftrace 和 kprobe 在运行中的内核插入探测点，不需要重新编译。kprobe 可以在任意函数的入口和返回点打印参数：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;p:my_probe do_sys_open filename=+0(%si):string&#39;</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /sys/kernel/debug/tracing/kprobe_events</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /sys/kernel/debug/tracing/events/kprobes/my_probe/enable</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /sys/kernel/debug/tracing/trace</span></span></code></pre></div><p>这些机制在 QEMU 中的价值是练习&quot;如何定位问题&quot;——真实生产环境的内核崩溃只会给你一份 vmcore 或一段 oops，在 QEMU 中熟悉了分析工具的使用，生产排障时才不会手忙脚乱。</p><h2 id="调试用-initramfs" tabindex="-1">调试用 initramfs <a class="header-anchor" href="#调试用-initramfs" aria-label="Permalink to “调试用 initramfs”">​</a></h2><p>内核调试的另一个基础设施是定制 initramfs。BusyBox 编译的最小 initramfs（几 MB）启动快、行为可控，是内核启动早期调试的标准环境。对于文件系统层的调试，QEMU 的 <code>-drive</code> 挂载磁盘镜像可以模拟任意块设备行为，而 <code>-virtfs</code> 通过 9p 协议直通宿主机目录，让虚拟机内的操作直接反映到宿主机文件系统——这在内核模块开发和测试时极其方便。</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 9p 共享目录：虚拟机内 mount -t 9p hostshare /mnt</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">qemu-system-x86_64</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -kernel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bzImage</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -initrd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> initramfs.cpio.gz</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -virtfs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> local,path=./shared,mount_tag=hostshare,security_model=none</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -append</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;console=ttyS0 nokaslr&quot;</span></span></code></pre></div><p>一个值得建立的工程习惯：为内核调试维护一份专用的 QEMU 启动脚本和 initramfs——脚本固定所有参数（GDB 端口、串口重定向、调试内核参数），initramfs 预装调试工具（crash、perf、调试符号）。内核调试的频率远低于应用调试，如果不预先准备好环境，每次调试都要重新摸索参数——环境的不确定性会在最需要专注的时候消耗注意力。</p>`,26)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};